.mms-minotaur{aspect-ratio:171/192;background-size:1500% 100%}.fighter.blue .mms-minotaur{background-image:url('myth/minotaur_swing_blue.png')}.fighter.red .mms-minotaur{background-image:url('myth/minotaur_swing_red.png')}
/* Dragon fire streak: patches of flame on the ground; units in it catch fire */
.fire{position:absolute;pointer-events:none;border-radius:50%;transform:translate(-50%,-50%);z-index:3;opacity:.95;transition:opacity .6s;
  background:radial-gradient(ellipse at 50% 60%,rgba(255,244,180,.95),rgba(255,170,50,.85) 30%,rgba(232,80,24,.6) 58%,rgba(140,30,10,0) 100%);animation:fireLick .35s ease-in-out infinite alternate}
.fire.out{opacity:0}
@keyframes fireLick{from{filter:brightness(.9) saturate(1)}to{filter:brightness(1.35) saturate(1.2)}}
.fighter.burning .pose{filter:drop-shadow(0 0 3px rgba(255,120,30,.95)) drop-shadow(0 -2px 2px rgba(255,200,60,.8))}
/* Mage turning a Minion into a Minotaur */
.poof{position:absolute;width:7%;aspect-ratio:1;border-radius:50%;pointer-events:none;z-index:5999;transform:translate(-50%,-50%) scale(.3);
  background:radial-gradient(circle,rgba(240,220,255,.95),rgba(170,100,255,.6) 45%,rgba(140,70,255,0) 70%);animation:poof .7s ease-out forwards}
@keyframes poof{to{transform:translate(-50%,-50%) scale(1.7);opacity:0}}
.roar.screech{border-color:rgba(255,236,150,.95);box-shadow:0 0 12px rgba(255,210,90,.9)}
@media (prefers-reduced-motion: reduce){.fire{animation:none}.poof{animation-duration:.2s}}
.mms-griffin{aspect-ratio:261/256}

var FIRES=[];
// Dragon fire run: at the start of the battle it comes in from beyond the enemy's edge, flies low and fast over the enemy's side
// to the middle of the field, turns and flies back out the way it came, then returns a moment later and fights as normal.
// Over the enemy's side it leaves a streak of fire on the ground that burns for 5 seconds. Any enemy on the ground that touches it
// catches fire: 5 damage a second while the streak lasts and for 5 seconds after it goes out.
function swoopStep(f,dt){
  const S=f.swoop, T=f.T, Z=T.swoop, dir=f.team===HOLD?1:-1, mid=AW/2, R0=Z.turnR, sp=T.speed*Z.mult;
  const out=dir>0?AW+T.w*0.6:-T.w*0.6;
  f.target=null; f.engaged=false; f.lunge=-1;
  if(S.st===0){   // line up on the enemy army (the middle of it, top to bottom), turning toward the roomier side
    const ys=F.filter(o=>o.team!==f.team&&!o.dead&&!o.T.flying).map(o=>o.y).sort((a,b)=>a-b);
    const lo=f.h+3, hi=AH-3;
    S.y1=Math.max(lo,Math.min(hi,ys.length?ys[ys.length>>1]:AH/2));
    S.up=S.y1+2*R0<=hi?1:-1; S.cy=S.y1+S.up*R0; S.a=0;
    f.x=out; f.y=S.y1; S.st=1; S.drop=0; S.px=f.x; S.py=f.y; }
  let nx=f.x, ny=f.y;
  if(S.st===1){ nx=f.x-dir*sp*dt; if((nx-mid)*dir<=0){ nx=mid; S.st=2; } }                      // in over the enemy's side
  else if(S.st===2){ S.a=Math.min(Math.PI,S.a+sp/R0*dt);                                           // the turn
    nx=mid-dir*R0*Math.sin(S.a); ny=S.cy-S.up*R0*Math.cos(S.a); if(S.a>=Math.PI) S.st=3; }
  else if(S.st===3){ nx=f.x+dir*sp*dt; if((nx-out)*dir>=0){ nx=out; S.st=4; S.t=0; } }             // back out
  else { S.t+=dt; if(S.t>=Z.wait) f.swoop=null; f.vx=0; f.vy=0; f.walking=true; return; }        // off the edge a moment, then back to fight
  f.vx=nx-f.x; f.vy=ny-f.y; f.walking=true; f.phase+=dt*9; if(Math.abs(f.vx)>1e-4) f.face=f.vx>0?1:-1;
  // fire on the ground behind it, while it's over the enemy's side of the field
  const onTheirSide=(nx-mid)*dir>0.5&&nx>0&&nx<AW;
  S.drop+=Math.hypot(nx-S.px,ny-S.py); S.px=nx; S.py=ny;
  if(onTheirSide&&S.drop>=Z.fire.gap){ S.drop=0; dropFire(f,nx,ny); }
}
function dropFire(f,x,y){
  const Z=f.T.swoop.fire, el=document.createElement('div'); el.className='fire';
  el.style.left=x+'%'; el.style.top=(y/AH*100)+'%'; el.style.width=(2*Z.r*1.25)+'%'; el.style.height=(2*Z.r*0.7/AH*100)+'%';
  arena.appendChild(el);
  FIRES.push({x,y,r:Z.r,until:clock+Z.dur,after:Z.after,dps:Z.dps,team:f.team,el});
}
function fireStep(dt){
  for(let i=FIRES.length-1;i>=0;i--){ const P=FIRES[i];
    if(clock>=P.until){ const el=P.el; el.classList.add('out'); setTimeout(()=>el.remove(),650); FIRES.splice(i,1); continue; }
    for(const o of F){ if(o.team===P.team||o.dead||o.pass||o.T.flying||o.onWall||o.ballista) continue;
      if(Math.hypot((o.x-P.x)/1.25,(o.y-P.y)/0.7)<=P.r){ if(!(o.burnUntil>clock)) o.burnAcc=0; o.burnUntil=Math.max(o.burnUntil||0,P.until+P.after); o.burnBy=P.team; o.burnDps=P.dps; } } }
  for(const o of F){
    const on=!o.dead&&o.burnUntil>clock;
    if(on){ o.burnAcc+=dt; while(o.burnAcc>=1&&!o.dead){ o.burnAcc-=1; hit(o,{T:{dmg:o.burnDps,beam:true},team:o.burnBy,hitKey:'fire'}); } }
    if(!!o.burnShown!==on){ o.burnShown=on; o.el.classList.toggle('burning',on); } }
}
// Griffin: at the start of the battle it swoops (twice its flying speed) to the enemy's front line and lands there. Every enemy on the
// ground near where it lands is knocked back a little and takes 2. Then it screeches: every enemy shooter misses its next 2 shots,
// and every enemy charge stops (a Rhino or Minotaur charge, a Megaraptor's sprint, an Alamosaurus that hasn't charged yet won't).
function gswoopStep(f,dt){
  const S=f.gswoop, G=f.T.gswoop, dir=f.team===HOLD?1:-1;
  if(!S.t||S.t.dead){ let best=null,bx=1e9;
    for(const o of F){ if(o.team===f.team||o.dead||o.pass||o.T.flying||o.ballista||o.onWall) continue;   // (the forest only hides units from shooters)
      const v=o.x*dir; if(v<bx){ bx=v; best=o; } }
    if(!best){ f.gswoop=null; return false; }
    S.t=best; }
  const t=S.t, tx=t.x-dir*2.5, ty=t.y, dx=tx-f.x, dy=ty-f.y, d=Math.hypot(dx,dy);
  f.target=t; f.engaged=false; S.time=(S.time||0)+dt;
  if(d>1.2&&S.time<6){ const st=f.T.speed*G.mult*dt; f.vx=dx/d*Math.min(st,d); f.vy=dy/d*Math.min(st,d); f.walking=true; f.phase+=dt*9; if(Math.abs(dx)>0.5) f.face=dx>0?1:-1; return true; }
  f.gswoop=null; griffinLand(f); return true;
}
function griffinLand(f){
  const G=f.T.gswoop;
  for(const o of F){ if(o.team===f.team||o.dead||o.pass||o.T.flying||o.ballista||o.onWall) continue;
    if(Math.hypot(o.x-f.x,o.y-f.y)<=G.radius){ hit(o,f,G.dmg/f.T.dmg); if(!o.dead) knockBack(f,o); } }
  const q=document.createElement('span'); q.className='quake'; q.addEventListener('animationend',()=>q.remove()); f.el.appendChild(q);
  screech(f);
}
function screech(f){
  const G=f.T.gswoop, hx=f.x+f.face*f.T.w*0.32, hy=f.y-f.alt-f.h*0.72;
  for(let k=0;k<3;k++){ const r=document.createElement('i'); r.className='roar screech'; r.style.left=hx+'%'; r.style.top=(hy/AH*100)+'%'; r.style.animationDelay=(k*0.18)+'s';
    r.addEventListener('animationend',()=>r.remove()); arena.appendChild(r); }
  for(const o of F){ if(o.team===f.team||o.dead) continue;
    if(shooter(o)) o.missShots=Math.max(o.missShots||0,G.miss);
    if(o.riders) for(const rd of o.riders) rd.att.missShots=G.miss;
    o.rchargeWait=false; if(o.rcharge) endCharge(o);
    if(o.chargeT>0) o.chargeT=0; if(o.T.charge) o.chargeUsed=true; o.chargeHit=false;
    o.boost=0; o.burstPending=false; o.mcharge=false; }
}
// Mage: every 2 seconds, a 20% chance to turn one of its side's Minions (any on the field, picked at random) into a Minotaur
function morphStep(f,dt){
  const M=f.T.morph; f.morphT=(f.morphT||0)+dt; if(f.morphT<M.every) return; f.morphT-=M.every;
  if(R()>=M.chance) return;
  const ms=F.filter(o=>o.team===f.team&&!o.dead&&!o.pass&&!o.fleeing&&o.key==='minion');
  if(!ms.length) return;
  const m=ms[Math.floor(R()*ms.length)], st=f.T.staff;
  zap(f,[{x:f.x+f.face*(st[0]-0.5)*f.T.w,y:f.y-f.alt-f.h*(1-st[1])},aimPt(m)]);
  morph(m,M.into);
}
function morph(m,key){
  const team=m.team; m.dead=true; m.gone=true; m.target=null; m.el.remove(); F.splice(F.indexOf(m),1);
  addUnit(team,key,m.x,m.y,false); const u=F[F.length-1]; u.face=m.face;
  HP0[team]+=Math.max(0,u.hp-Math.max(0,m.hp));   // the health bar grows with it
  const p=document.createElement('i'); p.className='poof'; p.style.left=m.x+'%'; p.style.top=((m.y-u.h*0.5)/AH*100)+'%';
  p.addEventListener('animationend',()=>p.remove()); arena.appendChild(p);
}
// Minotaur charge: its first hit kills outright; the big special units (Alamosaurus, Palaeoloxodon, Laser Tank, Dragon) instead take a
// normal hammer blow and are stunned for 4 seconds, even the ones nothing else can stun
function chargeHit(f,t){
  f.mcharge=false;
  if(SPECIAL(t.key)||t.key==='dragon'){ hit(t,f); if(!t.dead){ const d=f.T.mcharge.stun; t.stun=Math.max(t.stun,d); t.forceStun=clock+d; floatText(t,'Stunned','blk'); } return; }
  hit(t,{T:{dmg:Math.max(1,Math.ceil(t.hp)),beam:true},team:f.team,hitKey:'melee'});
}
